        q: "Почему APY выше APR при том же номинале?",
        a: "Потому что капитализация платит проценты на проценты. APY = (1 + r ÷ n)^n − 1: номинальные 12 % с ежемесячной капитализацией превращаются в (1,01)^12 − 1 = 12,6825 % эффективных — дополнительные 0,6825 пункта и есть проценты, которые зарабатывают ваши проценты. Чем чаще капитализация, тем шире разрыв: ежедневная бьёт ежемесячную, ежемесячная — годовую.",
